from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np
from rdkit.Geometry import Point3D
atoms=[('N',578,330),('C',475,267),('C',475,147),('C',579,86),('C',683,146),('C',683,267),('C',371,328),('C',265,345),('N',410,460),('N',325,558),('C',361,675),('O',478,686),('C',283,765),('C',165,744),('C',87,834),('C',128,949),('C',246,971),('C',325,878),('C',788,327),('C',907,327),('N',775,461),('N',866,562),('C',844,663),('O',723,686),('C',928,748),('C',1044,720),('C',1127,805),('C',1095,920),('C',978,951),('C',894,863)]
rw=Chem.RWMol()
for el,x,y in atoms:
 a=Chem.Atom(el)
 if el=='O': a.SetFormalCharge(-1)
 rw.AddAtom(a)
B=Chem.BondType
bonds=[(0,1,B.AROMATIC),(1,2,B.AROMATIC),(2,3,B.AROMATIC),(3,4,B.AROMATIC),(4,5,B.AROMATIC),(5,0,B.AROMATIC), (1,6,B.SINGLE),(6,7,B.SINGLE),(6,8,B.DOUBLE),(8,9,B.SINGLE),(9,10,B.DOUBLE),(10,11,B.SINGLE),(10,12,B.SINGLE),(5,18,B.SINGLE),(18,19,B.SINGLE),(18,20,B.DOUBLE),(20,21,B.SINGLE),(21,22,B.DOUBLE),(22,23,B.SINGLE),(22,24,B.SINGLE)]
for r in (list(range(12,18)),list(range(24,30))):
 for j in range(6): bonds.append((r[j],r[(j+1)%6],B.AROMATIC))
for i,j,t in bonds:rw.AddBond(i,j,t)
m=rw.GetMol();Chem.SanitizeMol(m)
conf=Chem.Conformer(m.GetNumAtoms())
for i,(el,x,y) in enumerate(atoms):conf.SetAtomPosition(i,Point3D((x-580)/85,(510-y)/85,0))
m.AddConformer(conf)
m=Chem.AddHs(m,addCoords=True)
for a in m.GetAtoms(): print(a.GetIdx(),a.GetSymbol(),[(n.GetIdx(),str(m.GetBondBetweenAtoms(a.GetIdx(),n.GetIdx()).GetBondType())) for n in a.GetNeighbors()])
coords=np.array(m.GetConformer().GetPositions()); symbols=[a.GetSymbol() for a in m.GetAtoms()]
# Add small out-of-plane tilting for selected phenyl rings, methyl hydrogen preserved
# Axis rotate phenyl around C10-C12, C22-C24, updating phenyl H atoms as well
for root,phenyl,theta in [(10,set(range(12,18)),np.deg2rad(28)),(22,set(range(24,30)),np.deg2rad(-26))]:
 target=min(phenyl);p=coords[root];unit=coords[target]-p;unit/=np.linalg.norm(unit)
 for idx in phenyl.copy():
  phenyl.update(n.GetIdx() for n in m.GetAtomWithIdx(idx).GetNeighbors() if n.GetSymbol()=='H')
 for idx in phenyl:
  v=coords[idx]-p; coords[idx]=p+v*np.cos(theta)+np.cross(unit,v)*np.sin(theta)+unit*np.dot(unit,v)*(1-np.cos(theta))
# 5 donor ring metal Mo at zero
symbols.extend(['Mo','C','O','N','C','C']);coords=np.vstack([coords,np.array([[0.,0.,0.], [0.1,0.17,1.96],[0.13,0.26,3.11],[0.05,-0.16,-2.15],[0.07,-0.21,-3.32],[0.10,-0.27,-4.78]])]);
# H3 attached acetonitrile methyl: carbon at -4.78, H at -5.15 (tetrahedrally pointing away from cyanide carbon)
symbols.extend(['H','H','H']);coords=np.vstack([coords,np.array([[1.02,-0.27,-5.14],[-0.36,0.52,-5.15],[-0.41,-1.06,-5.14]])]);
def save(xyz,path):
 with open(path,'w') as f:
  f.write(f'{len(xyz)}\nMo(CO)(MeCN) pyridine bis-hydrazone phenolate complex\n');
  for s,co in zip(symbols,xyz):f.write(f'{s:<2} {co[0]: .7f} {co[1]: .7f} {co[2]: .7f}\n')
save(coords,'initial.xyz')
print('total atoms',len(symbols),'Mo idx',len(symbols)-9)
